from typing import Any, Optional

import torch
from vllm.model_executor.layers.quantization.auto_gptq import AutoGPTQConfig
from vllm.model_executor.layers.quantization.base_config import QuantizationConfig, QuantizeMethodBase

_FP8_SYNTH = {
    "quant_method": "fp8",
    "activation_scheme": "dynamic",
    "weight_block_size": [32, 32],
    "scale_fmt": "ue8m0",
    "expert_dtype": "fp4",
}


class DSV41AutoRoundConfig(QuantizationConfig):
    """auto-round auto_gptq (experts-only) for DeepSeek-V4.1: built-in GPTQ-MoE + fp8 dense."""

    def __init__(self, autoround_cfg: dict[str, Any]):
        self._ar_cfg = autoround_cfg
        from vllm.models.deepseek_v4_1.quant_config import DeepseekV4FP8Config

        self._fp8_cfg = DeepseekV4FP8Config.from_config(dict(_FP8_SYNTH))
        translated = {
            "bits": autoround_cfg.get("bits", 4),
            "group_size": autoround_cfg.get("group_size", 32),
            "sym": autoround_cfg.get("sym", True),
            "desc_act": autoround_cfg.get("desc_act", False),
            "lm_head": autoround_cfg.get("quant_lm_head", False),
        }
        self._gptq = AutoGPTQConfig.from_config(translated)

    @classmethod
    def get_name(cls) -> str:
        return "dsv41_autoround"

    @classmethod
    def get_supported_act_dtypes(cls) -> list[torch.dtype]:
        return [torch.bfloat16, torch.float16]

    @classmethod
    def get_min_capability(cls) -> int:
        return 80

    @staticmethod
    def get_config_filenames() -> list[str]:
        return []

    @classmethod
    def from_config(cls, config: dict[str, Any]) -> "DSV41AutoRoundConfig":
        return cls(config)

    @classmethod
    def override_quantization_method(cls, hf_quant_cfg, user_quant, hf_config=None) -> Optional[str]:
        if user_quant not in (None, cls.get_name()):
            return None
        if not hf_quant_cfg:
            return None
        if hf_quant_cfg.get("quant_method") != "auto-round":
            return None
        if "auto_gptq" not in str(hf_quant_cfg.get("packing_format", "")):
            return None
        model_type = getattr(hf_config, "model_type", "") if hf_config is not None else ""
        if not str(model_type).startswith("deepseek_v4"):
            return None
        return cls.get_name()

    def get_quant_method(self, layer, prefix: str) -> Optional[QuantizeMethodBase]:
        from vllm.model_executor.layers.fused_moe.routed_experts import RoutedExperts
        from vllm.model_executor.layers.linear import LinearBase

        if isinstance(layer, LinearBase):
            # dense fp8 (untouched by the experts-only export) -> built-in mxfp8 linear
            return self._fp8_cfg.get_quant_method(layer, prefix)
        if isinstance(layer, RoutedExperts):
            # auto_gptq experts -> built-in GPTQ MoE (marlin / wna16)
            return self._gptq.get_quant_method(layer, prefix)
