{"content": """"DSV41Mxfp8RowwiseConfig: serve D1-ar-v2 checkpoints (dense OCP-MXFP8 rowwise).

Checkpoint layout (produced by build_d1_ar_v2.py, LOSSLESS scale expansion):
- dense LinearBase (attn wq_a/wq_b/wkv/wo_a/wo_b, shared_experts, engram.wkv,
  indexer.wq_b, main_proj): official blockwise fp8 [32,32] ue8m0 converted to
  OCP MXFP8 rowwise -- `.weight` fp8_e4m3 (bytes untouched) + `.weight_scale`
  uint8 e8m0-bits [N, K/32].
- RoutedExperts: official packed MXFP4 (`.weight` int8 + `.scale` e8m0), untouched.
- engram embed tables: MXFP4 packed (served via the plugin's engram patch,
  DSV41_ENGRAM_DTYPE=fp4).

Dense branch dequantizes fp8xE8M0-rowwise weights to bf16 at load time -- this is
numerically identical to the official blockwise fp8 values (e4m3 x 2^e is exact in
bf16), so gsm8k parity with the baseline is preserved by construction.
"""
from typing import Any, Optional

import torch
import torch.nn.functional as F
from vllm.model_executor.layers.quantization.base_config import QuantizationConfig, QuantizeMethodBase

_FP8_OFFICIAL_CFG = {
    "quant_method": "fp8",
    "activation_scheme": "dynamic",
    "weight_block_size": [32, 32],
    "scale_fmt": "ue8m0",
    "expert_dtype": "fp4",
}


class V41Mxfp8RowwiseLinearMethod(QuantizeMethodBase):
    """Weight-only OCP-MXFP8-rowwise -> bf16 dequant at load, plain bf16 GEMM."""

    def create_weights(self, layer, input_size_per_partition, output_partition_sizes,
                       input_size, output_size, params_dtype, **extra_weight_attrs):
        from vllm.model_executor.parameter import ModelWeightParameter

        weight_loader = extra_weight_attrs.get("weight_loader")
        out_features = sum(output_partition_sizes)
        weight = ModelWeightParameter(
            data=torch.empty(out_features, input_size_per_partition, dtype=torch.float8_e4m3fn),
            input_dim=1,
            output_dim=0,
            weight_loader=weight_loader,
        )
        weight_scale = ModelWeightParameter(
            data=torch.empty(out_features, input_size_per_partition // 32, dtype=torch.uint8),
            input_dim=1,
            output_dim=0,
            weight_loader=weight_loader,
        )
        layer.register_parameter("weight", weight)
        layer.register_parameter("weight_scale", weight_scale)

    def process_weights_after_loading(self, layer):
        w = layer.weight.data  # fp8_e4m3 [N, K]
        s = layer.weight_scale.data  # uint8 e8m0 bits [N, K/32]
        n, k = w.shape
        scale = torch.pow(2.0, s.float() - 127).unsqueeze(-1)  # [N, K/32, 1]
        dq = (w.float().view(n, k // 32, 32) * scale).view(n, k).to(torch.bfloat16)
        layer.weight = torch.nn.Parameter(dq, requires_grad=False)
        del layer.weight_scale

    def apply(self, layer, x, bias=None):
        return F.linear(x, layer.weight, bias)


class DSV41Mxfp8RowwiseConfig(QuantizationConfig):
    """Claims D1-ar-v2 checkpoints (quant_method == "dsv41_mxfp_rowwise")."""

    def __init__(self, hf_config=None):
        from vllm.models.deepseek_v4_1 import DeepseekV4FP8Config as DeepseekV41FP8Config

        # experts stay in official packed-MXFP4 layout -> built-in V4.1 fp4 MoE path
        self._v41_fp8 = DeepseekV41FP8Config.from_config(_FP8_OFFICIAL_CFG)

    @classmethod
    def get_name(cls) -> str:
        return "dsv41_mxfp_rowwise"

    @classmethod
    def get_supported_act_dtypes(cls) -> list[torch.dtype]:
        return [torch.bfloat16, torch.float16]

    @classmethod
    def get_min_capability(cls) -> int:
        return 80

    @staticmethod
    def get_config_filenames() -> list[str]:
        return []

    @classmethod
    def from_config(cls, config: dict[str, Any]) -> "DSV41Mxfp8RowwiseConfig":
        return cls()

    @classmethod
    def override_quantization_method(cls, hf_quant_cfg, user_quant, hf_config=None) -> Optional[str]:
        if user_quant not in (None, cls.get_name()):
