class DSV41AutoRoundMxfpConfig(QuantizationConfig):
    """auto-round mxfp8/mxfp4 (llm_compressor packing) dispatch for deepseek_v4 family."""

    def __init__(self):
        from vllm.models.deepseek_v4_1 import DeepseekV4FP8Config as DeepseekV41FP8Config

        # experts stay in official packed-MXFP4 layout -> built-in V4.1 FP4 MoE path
        self._v41_fp8 = DeepseekV41FP8Config.from_config(_FP8_OFFICIAL_CFG)

    @classmethod
    def get_name(cls) -> str:
        return "dsv41_autoround_mxfp"

    @classmethod
    def get_supported_act_dtypes(cls) -> list[torch.dtype]:
        return [torch.bfloat16, torch.float16]

    @classmethod
    def get_min_capability(cls) -> int:
        return 75

    @staticmethod
    def get_config_filenames() -> list[str]:
        return []

    @classmethod
    def from_config(cls, config: dict[str, Any]) -> "DSV41AutoRoundMxfpConfig":
        return cls()

    @classmethod
    def override_quantization_method(cls, hf_quant_cfg, user_quant, hf_config=None) -> Optional[str]:
        if user_quant not in (None, cls.get_name()):
            return None
        if not hf_quant_cfg or hf_quant_cfg.get("quant_method") != "auto-round":
            return None
        if "llm_compressor" not in str(hf_quant_cfg.get("packing_format", "")):
            return None
        model_type = getattr(hf_config, "model_type", "") if hf_config is not None else ""
        if not str(model_type).startswith("deepseek_v4"):
            return None
        return cls.get_name()

    def get_quant_method(self, layer, prefix: str) -> Optional[QuantizeMethodBase]:
        from vllm.model_executor.layers.fused_moe.routed_experts import RoutedExperts
        from vllm.model_executor.layers.linear import LinearBase, UnquantizedLinearMethod

        if isinstance(layer, RoutedExperts):
            return self._v41_fp8.get_quant_method(layer, prefix)
        if isinstance(layer, LinearBase):
            if "gate" in prefix:
